window.MG_LAZY_DATA["data/lazy/owner-courses/a375-d1003e8000522e49.json"]={sha256:"d1003e8000522e49df06e84be68aa0c52592ae8979038b56bafa3dcea5e5b2ec",value:{"id":"a375","title":"安全多方計算系統","titleEn":"Secure multiparty-computation systems","category":"computing","kind":"course","summary":"以秘密分享、協議威脅模型與通訊成本串連 16 個原創技術單元、32 步；涵蓋原理解析、架構圖、假想量化、合成資料實驗、競爭失效原因及可重算驗收。","summaryEn":"Sixteen original technical units and 32 tasks connect secret sharing, protocol threat models and communication with principles, architectures, assumed calculations, synthetic experiments, competing failure causes and reproducible acceptance.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"stepCount":32,"estimatedMinutes":1120,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"stages":[{"id":"a375-v11-stage01","order":1,"title":"參與與威脅","titleEn":"Parties and threats","description":"四個技術單元依序完成「參與與威脅」的架構與證據，共八步可分別儲存的本地科教實作。","descriptionEn":"Four technical units develop parties and threats through eight separately saved local educational tasks.","steps":[{"id":"a375-v11-01","order":1,"sequence":1,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":[],"title":"參與方角色：原理與架構","titleEn":"Party roles: principles and architecture","objective":"以「參與方角色」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for party roles.","instruction":"先觀察師傅的「參與方角色」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：MPC 保證依不串通或容忍串通的假設而定。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「對三方玩具計算標示哪組被假設誠實。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for party roles. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: MPC guarantees depend on noncollusion or tolerated collusion. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Mark assumed-honest groups in a three-party toy computation. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"對三方玩具計算標示哪組被假設誠實。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Mark assumed-honest groups in a three-party toy computation. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：參與方越多就不需威脅模型。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: More parties remove the need for threat models. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「參與方角色」兩情境架構圖、假設與可反駁預測，並說明「對三方玩具計算標示哪組被假設誠實。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for party roles; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-01-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"MPC 保證依不串通或容忍串通的假設而定。","textEn":"MPC guarantees depend on noncollusion or tolerated collusion.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-01-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"對三方玩具計算標示哪組被假設誠實。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Mark assumed-honest groups in a three-party toy computation. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"},{"id":"a375-v11-01-k3","title":"本課量化算例","titleEn":"Course quantitative example","text":"玩具模環 Z₁₇ 將秘密 s=9 分享為 4、7、15，因為 (4+7+15) mod17=9。每個分享若按正確隨機協議產生可隱藏原值；此固定例子不構成安全實作。加上公開值 3 後可只改一個分享為 7，和變為 12。","textEn":"Toy shares 4,7,15 in Z17 sum to secret 9. Secure hiding requires a correct randomized protocol; these fixed numbers are not a secure implementation. Adding public 3 to one share changes the reconstructed sum to 12.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"審查「參與方角色」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for party roles?","options":["MPC 保證依不串通或容忍串通的假設而定。","參與方越多就不需威脅模型。","只要一次輸出符合預期，就能推定「參與方角色」對所有資料量、版本與故障條件都成立。"],"optionsEn":["MPC guarantees depend on noncollusion or tolerated collusion.","More parties remove the need for threat models.","One matching output proves party roles for all sizes, versions and failure conditions."],"answer":0,"explanation":"MPC 保證依不串通或容忍串通的假設而定。 對三方玩具計算標示哪組被假設誠實。 因此「參與方越多就不需威脅模型。」混淆了本單元必須分開檢查的條件。","explanationEn":"MPC guarantees depend on noncollusion or tolerated collusion. Mark assumed-honest groups in a three-party toy computation. The alternative \"More parties remove the need for threat models.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-02","order":2,"sequence":2,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-01"],"title":"參與方角色：實驗與證據","titleEn":"Party roles: experiments and evidence","objective":"以「參與方角色」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for party roles.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「對三方玩具計算標示哪組被假設誠實。」；將結果與「MPC 保證依不串通或容忍串通的假設而定。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Mark assumed-honest groups in a three-party toy computation. Compare results against: MPC guarantees depend on noncollusion or tolerated collusion. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"對三方玩具計算標示哪組被假設誠實。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Mark assumed-honest groups in a three-party toy computation. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：參與方越多就不需威脅模型。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: More parties remove the need for threat models. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「參與方角色」實驗輸出、基準差異、誤判排除與限用條件；解釋「參與方越多就不需威脅模型。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for party roles; explain why this claim fails: More parties remove the need for threat models.","knowledge":[{"id":"a375-v11-02-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"MPC 保證依不串通或容忍串通的假設而定。","textEn":"MPC guarantees depend on noncollusion or tolerated collusion.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-02-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"對三方玩具計算標示哪組被假設誠實。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Mark assumed-honest groups in a three-party toy computation. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"},{"id":"a375-v11-02-k3","title":"本課量化算例","titleEn":"Course quantitative example","text":"玩具模環 Z₁₇ 將秘密 s=9 分享為 4、7、15，因為 (4+7+15) mod17=9。每個分享若按正確隨機協議產生可隱藏原值；此固定例子不構成安全實作。加上公開值 3 後可只改一個分享為 7，和變為 12。","textEn":"Toy shares 4,7,15 in Z17 sum to secret 9. Secure hiding requires a correct randomized protocol; these fixed numbers are not a secure implementation. Adding public 3 to one share changes the reconstructed sum to 12.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"審查「參與方角色」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for party roles?","options":["參與方越多就不需威脅模型。","對三方玩具計算標示哪組被假設誠實。","先把「參與方角色」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["More parties remove the need for threat models.","Mark assumed-honest groups in a three-party toy computation.","Tune the displayed party roles result to the expected value and count that agreement as independent validation."],"answer":1,"explanation":"MPC 保證依不串通或容忍串通的假設而定。 對三方玩具計算標示哪組被假設誠實。 因此「參與方越多就不需威脅模型。」混淆了本單元必須分開檢查的條件。","explanationEn":"MPC guarantees depend on noncollusion or tolerated collusion. Mark assumed-honest groups in a three-party toy computation. The alternative \"More parties remove the need for threat models.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-03","order":3,"sequence":3,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-02"],"title":"誠實與惡意：原理與架構","titleEn":"Honest and malicious behavior: principles and architecture","objective":"以「誠實與惡意」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for honest and malicious behavior.","instruction":"先觀察師傅的「誠實與惡意」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：半誠實與惡意模型允許的偏離不同。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「列出遵守協議但分析記錄與偽造訊息差異。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for honest and malicious behavior. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Semi-honest and malicious models allow different deviations. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Distinguish analyzing compliant transcripts from forged messages. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"列出遵守協議但分析記錄與偽造訊息差異。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Distinguish analyzing compliant transcripts from forged messages. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：半誠實安全自動等於惡意安全。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Semi-honest security automatically implies malicious security. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「誠實與惡意」兩情境架構圖、假設與可反駁預測，並說明「列出遵守協議但分析記錄與偽造訊息差異。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for honest and malicious behavior; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-03-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"半誠實與惡意模型允許的偏離不同。","textEn":"Semi-honest and malicious models allow different deviations.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-03-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"列出遵守協議但分析記錄與偽造訊息差異。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Distinguish analyzing compliant transcripts from forged messages. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「誠實與惡意」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for honest and malicious behavior?","options":["半誠實安全自動等於惡意安全。","只要一次輸出符合預期，就能推定「誠實與惡意」對所有資料量、版本與故障條件都成立。","半誠實與惡意模型允許的偏離不同。"],"optionsEn":["Semi-honest security automatically implies malicious security.","One matching output proves honest and malicious behavior for all sizes, versions and failure conditions.","Semi-honest and malicious models allow different deviations."],"answer":2,"explanation":"半誠實與惡意模型允許的偏離不同。 列出遵守協議但分析記錄與偽造訊息差異。 因此「半誠實安全自動等於惡意安全。」混淆了本單元必須分開檢查的條件。","explanationEn":"Semi-honest and malicious models allow different deviations. Distinguish analyzing compliant transcripts from forged messages. The alternative \"Semi-honest security automatically implies malicious security.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-04","order":4,"sequence":4,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-03"],"title":"誠實與惡意：實驗與證據","titleEn":"Honest and malicious behavior: experiments and evidence","objective":"以「誠實與惡意」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for honest and malicious behavior.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「列出遵守協議但分析記錄與偽造訊息差異。」；將結果與「半誠實與惡意模型允許的偏離不同。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Distinguish analyzing compliant transcripts from forged messages. Compare results against: Semi-honest and malicious models allow different deviations. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"列出遵守協議但分析記錄與偽造訊息差異。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Distinguish analyzing compliant transcripts from forged messages. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：半誠實安全自動等於惡意安全。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Semi-honest security automatically implies malicious security. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「誠實與惡意」實驗輸出、基準差異、誤判排除與限用條件；解釋「半誠實安全自動等於惡意安全。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for honest and malicious behavior; explain why this claim fails: Semi-honest security automatically implies malicious security.","knowledge":[{"id":"a375-v11-04-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"半誠實與惡意模型允許的偏離不同。","textEn":"Semi-honest and malicious models allow different deviations.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-04-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"列出遵守協議但分析記錄與偽造訊息差異。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Distinguish analyzing compliant transcripts from forged messages. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「誠實與惡意」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for honest and malicious behavior?","options":["列出遵守協議但分析記錄與偽造訊息差異。","半誠實安全自動等於惡意安全。","先把「誠實與惡意」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Distinguish analyzing compliant transcripts from forged messages.","Semi-honest security automatically implies malicious security.","Tune the displayed honest and malicious behavior result to the expected value and count that agreement as independent validation."],"answer":0,"explanation":"半誠實與惡意模型允許的偏離不同。 列出遵守協議但分析記錄與偽造訊息差異。 因此「半誠實安全自動等於惡意安全。」混淆了本單元必須分開檢查的條件。","explanationEn":"Semi-honest and malicious models allow different deviations. Distinguish analyzing compliant transcripts from forged messages. The alternative \"Semi-honest security automatically implies malicious security.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-05","order":5,"sequence":5,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-04"],"title":"分享代數：原理與架構","titleEn":"Sharing algebra: principles and architecture","objective":"以「分享代數」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for sharing algebra.","instruction":"先觀察師傅的「分享代數」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：加法分享的總和在指定有限環重建秘密。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「重算本課三個分享及模數折返。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for sharing algebra. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Additive shares reconstruct by summing in a specified finite ring. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Recalculate the three shares and modular reduction. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"重算本課三個分享及模數折返。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Recalculate the three shares and modular reduction. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：直接做一般整數加法便是環重建。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Ordinary integer addition alone reconstructs ring secrets. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「分享代數」兩情境架構圖、假設與可反駁預測，並說明「重算本課三個分享及模數折返。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for sharing algebra; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-05-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"加法分享的總和在指定有限環重建秘密。","textEn":"Additive shares reconstruct by summing in a specified finite ring.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-05-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"重算本課三個分享及模數折返。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Recalculate the three shares and modular reduction. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「分享代數」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for sharing algebra?","options":["直接做一般整數加法便是環重建。","加法分享的總和在指定有限環重建秘密。","只要一次輸出符合預期，就能推定「分享代數」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Ordinary integer addition alone reconstructs ring secrets.","Additive shares reconstruct by summing in a specified finite ring.","One matching output proves sharing algebra for all sizes, versions and failure conditions."],"answer":1,"explanation":"加法分享的總和在指定有限環重建秘密。 重算本課三個分享及模數折返。 因此「直接做一般整數加法便是環重建。」混淆了本單元必須分開檢查的條件。","explanationEn":"Additive shares reconstruct by summing in a specified finite ring. Recalculate the three shares and modular reduction. The alternative \"Ordinary integer addition alone reconstructs ring secrets.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-06","order":6,"sequence":6,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-05"],"title":"分享代數：實驗與證據","titleEn":"Sharing algebra: experiments and evidence","objective":"以「分享代數」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for sharing algebra.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「重算本課三個分享及模數折返。」；將結果與「加法分享的總和在指定有限環重建秘密。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Recalculate the three shares and modular reduction. Compare results against: Additive shares reconstruct by summing in a specified finite ring. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"重算本課三個分享及模數折返。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Recalculate the three shares and modular reduction. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：直接做一般整數加法便是環重建。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Ordinary integer addition alone reconstructs ring secrets. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「分享代數」實驗輸出、基準差異、誤判排除與限用條件；解釋「直接做一般整數加法便是環重建。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for sharing algebra; explain why this claim fails: Ordinary integer addition alone reconstructs ring secrets.","knowledge":[{"id":"a375-v11-06-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"加法分享的總和在指定有限環重建秘密。","textEn":"Additive shares reconstruct by summing in a specified finite ring.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-06-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"重算本課三個分享及模數折返。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Recalculate the three shares and modular reduction. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「分享代數」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for sharing algebra?","options":["直接做一般整數加法便是環重建。","先把「分享代數」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。","重算本課三個分享及模數折返。"],"optionsEn":["Ordinary integer addition alone reconstructs ring secrets.","Tune the displayed sharing algebra result to the expected value and count that agreement as independent validation.","Recalculate the three shares and modular reduction."],"answer":2,"explanation":"加法分享的總和在指定有限環重建秘密。 重算本課三個分享及模數折返。 因此「直接做一般整數加法便是環重建。」混淆了本單元必須分開檢查的條件。","explanationEn":"Additive shares reconstruct by summing in a specified finite ring. Recalculate the three shares and modular reduction. The alternative \"Ordinary integer addition alone reconstructs ring secrets.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-07","order":7,"sequence":7,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-06"],"title":"隨機性要求：原理與架構","titleEn":"Randomness requirements: principles and architecture","objective":"以「隨機性要求」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for randomness requirements.","instruction":"先觀察師傅的「隨機性要求」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：分享隱私依賴足夠隨機且不重複的隨機量。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「僅以符號分析重用隨機量可能帶來的關聯。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for randomness requirements. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Share privacy needs adequate, unreused randomness. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Analyze reused-randomness correlations symbolically. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"僅以符號分析重用隨機量可能帶來的關聯。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Analyze reused-randomness correlations symbolically. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：固定教學分享可直接用於保密生產資料。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Fixed teaching shares securely protect production data. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「隨機性要求」兩情境架構圖、假設與可反駁預測，並說明「僅以符號分析重用隨機量可能帶來的關聯。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for randomness requirements; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-07-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"分享隱私依賴足夠隨機且不重複的隨機量。","textEn":"Share privacy needs adequate, unreused randomness.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-07-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"僅以符號分析重用隨機量可能帶來的關聯。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Analyze reused-randomness correlations symbolically. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「隨機性要求」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for randomness requirements?","options":["分享隱私依賴足夠隨機且不重複的隨機量。","固定教學分享可直接用於保密生產資料。","只要一次輸出符合預期，就能推定「隨機性要求」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Share privacy needs adequate, unreused randomness.","Fixed teaching shares securely protect production data.","One matching output proves randomness requirements for all sizes, versions and failure conditions."],"answer":0,"explanation":"分享隱私依賴足夠隨機且不重複的隨機量。 僅以符號分析重用隨機量可能帶來的關聯。 因此「固定教學分享可直接用於保密生產資料。」混淆了本單元必須分開檢查的條件。","explanationEn":"Share privacy needs adequate, unreused randomness. Analyze reused-randomness correlations symbolically. The alternative \"Fixed teaching shares securely protect production data.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-08","order":8,"sequence":8,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-07"],"title":"隨機性要求：實驗與證據","titleEn":"Randomness requirements: experiments and evidence","objective":"以「隨機性要求」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for randomness requirements.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「僅以符號分析重用隨機量可能帶來的關聯。」；將結果與「分享隱私依賴足夠隨機且不重複的隨機量。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Analyze reused-randomness correlations symbolically. Compare results against: Share privacy needs adequate, unreused randomness. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"僅以符號分析重用隨機量可能帶來的關聯。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Analyze reused-randomness correlations symbolically. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：固定教學分享可直接用於保密生產資料。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Fixed teaching shares securely protect production data. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「隨機性要求」實驗輸出、基準差異、誤判排除與限用條件；解釋「固定教學分享可直接用於保密生產資料。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for randomness requirements; explain why this claim fails: Fixed teaching shares securely protect production data.","knowledge":[{"id":"a375-v11-08-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"分享隱私依賴足夠隨機且不重複的隨機量。","textEn":"Share privacy needs adequate, unreused randomness.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-08-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"僅以符號分析重用隨機量可能帶來的關聯。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Analyze reused-randomness correlations symbolically. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「隨機性要求」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for randomness requirements?","options":["固定教學分享可直接用於保密生產資料。","僅以符號分析重用隨機量可能帶來的關聯。","先把「隨機性要求」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Fixed teaching shares securely protect production data.","Analyze reused-randomness correlations symbolically.","Tune the displayed randomness requirements result to the expected value and count that agreement as independent validation."],"answer":1,"explanation":"分享隱私依賴足夠隨機且不重複的隨機量。 僅以符號分析重用隨機量可能帶來的關聯。 因此「固定教學分享可直接用於保密生產資料。」混淆了本單元必須分開檢查的條件。","explanationEn":"Share privacy needs adequate, unreused randomness. Analyze reused-randomness correlations symbolically. The alternative \"Fixed teaching shares securely protect production data.\" conflates conditions that must be checked separately."}}]},{"id":"a375-v11-stage02","order":2,"title":"分享與運算","titleEn":"Sharing and computation","description":"四個技術單元依序完成「分享與運算」的架構與證據，共八步可分別儲存的本地科教實作。","descriptionEn":"Four technical units develop sharing and computation through eight separately saved local educational tasks.","steps":[{"id":"a375-v11-09","order":1,"sequence":9,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-08"],"title":"公開加法：原理與架構","titleEn":"Public addition: principles and architecture","objective":"以「公開加法」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for public addition.","instruction":"先觀察師傅的「公開加法」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：公開常數加到一個加法分享即可調整總秘密。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「比較只加一次與每個分享都加常數。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for public addition. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Adding a public constant to one additive share changes the secret. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Compare adding once versus adding to every share. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"比較只加一次與每個分享都加常數。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Compare adding once versus adding to every share. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：每個分享都加 c 後總秘密只加 c。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Adding c to every share adds only c overall. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「公開加法」兩情境架構圖、假設與可反駁預測，並說明「比較只加一次與每個分享都加常數。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for public addition; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-09-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"公開常數加到一個加法分享即可調整總秘密。","textEn":"Adding a public constant to one additive share changes the secret.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-09-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"比較只加一次與每個分享都加常數。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Compare adding once versus adding to every share. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「公開加法」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for public addition?","options":["每個分享都加 c 後總秘密只加 c。","只要一次輸出符合預期，就能推定「公開加法」對所有資料量、版本與故障條件都成立。","公開常數加到一個加法分享即可調整總秘密。"],"optionsEn":["Adding c to every share adds only c overall.","One matching output proves public addition for all sizes, versions and failure conditions.","Adding a public constant to one additive share changes the secret."],"answer":2,"explanation":"公開常數加到一個加法分享即可調整總秘密。 比較只加一次與每個分享都加常數。 因此「每個分享都加 c 後總秘密只加 c。」混淆了本單元必須分開檢查的條件。","explanationEn":"Adding a public constant to one additive share changes the secret. Compare adding once versus adding to every share. The alternative \"Adding c to every share adds only c overall.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-10","order":2,"sequence":10,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-09"],"title":"公開加法：實驗與證據","titleEn":"Public addition: experiments and evidence","objective":"以「公開加法」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for public addition.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「比較只加一次與每個分享都加常數。」；將結果與「公開常數加到一個加法分享即可調整總秘密。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Compare adding once versus adding to every share. Compare results against: Adding a public constant to one additive share changes the secret. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"比較只加一次與每個分享都加常數。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Compare adding once versus adding to every share. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：每個分享都加 c 後總秘密只加 c。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Adding c to every share adds only c overall. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「公開加法」實驗輸出、基準差異、誤判排除與限用條件；解釋「每個分享都加 c 後總秘密只加 c。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for public addition; explain why this claim fails: Adding c to every share adds only c overall.","knowledge":[{"id":"a375-v11-10-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"公開常數加到一個加法分享即可調整總秘密。","textEn":"Adding a public constant to one additive share changes the secret.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-10-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"比較只加一次與每個分享都加常數。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Compare adding once versus adding to every share. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「公開加法」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for public addition?","options":["比較只加一次與每個分享都加常數。","每個分享都加 c 後總秘密只加 c。","先把「公開加法」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Compare adding once versus adding to every share.","Adding c to every share adds only c overall.","Tune the displayed public addition result to the expected value and count that agreement as independent validation."],"answer":0,"explanation":"公開常數加到一個加法分享即可調整總秘密。 比較只加一次與每個分享都加常數。 因此「每個分享都加 c 後總秘密只加 c。」混淆了本單元必須分開檢查的條件。","explanationEn":"Adding a public constant to one additive share changes the secret. Compare adding once versus adding to every share. The alternative \"Adding c to every share adds only c overall.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-11","order":3,"sequence":11,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-10"],"title":"秘密加法：原理與架構","titleEn":"Secret addition: principles and architecture","objective":"以「秘密加法」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for secret addition.","instruction":"先觀察師傅的「秘密加法」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：兩個秘密的對應分享可區域性相加。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「用玩具向量逐方相加並重建核對。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for secret addition. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Corresponding shares of two secrets can be added locally. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Add toy share vectors by party and verify reconstruction. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"用玩具向量逐方相加並重建核對。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Add toy share vectors by party and verify reconstruction. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：秘密加法必須先公開兩個明文。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Secret addition requires revealing both plaintexts. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「秘密加法」兩情境架構圖、假設與可反駁預測，並說明「用玩具向量逐方相加並重建核對。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for secret addition; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-11-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"兩個秘密的對應分享可區域性相加。","textEn":"Corresponding shares of two secrets can be added locally.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-11-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"用玩具向量逐方相加並重建核對。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Add toy share vectors by party and verify reconstruction. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「秘密加法」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for secret addition?","options":["秘密加法必須先公開兩個明文。","兩個秘密的對應分享可區域性相加。","只要一次輸出符合預期，就能推定「秘密加法」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Secret addition requires revealing both plaintexts.","Corresponding shares of two secrets can be added locally.","One matching output proves secret addition for all sizes, versions and failure conditions."],"answer":1,"explanation":"兩個秘密的對應分享可區域性相加。 用玩具向量逐方相加並重建核對。 因此「秘密加法必須先公開兩個明文。」混淆了本單元必須分開檢查的條件。","explanationEn":"Corresponding shares of two secrets can be added locally. Add toy share vectors by party and verify reconstruction. The alternative \"Secret addition requires revealing both plaintexts.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-12","order":4,"sequence":12,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-11"],"title":"秘密加法：實驗與證據","titleEn":"Secret addition: experiments and evidence","objective":"以「秘密加法」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for secret addition.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「用玩具向量逐方相加並重建核對。」；將結果與「兩個秘密的對應分享可區域性相加。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Add toy share vectors by party and verify reconstruction. Compare results against: Corresponding shares of two secrets can be added locally. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"用玩具向量逐方相加並重建核對。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Add toy share vectors by party and verify reconstruction. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：秘密加法必須先公開兩個明文。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Secret addition requires revealing both plaintexts. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「秘密加法」實驗輸出、基準差異、誤判排除與限用條件；解釋「秘密加法必須先公開兩個明文。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for secret addition; explain why this claim fails: Secret addition requires revealing both plaintexts.","knowledge":[{"id":"a375-v11-12-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"兩個秘密的對應分享可區域性相加。","textEn":"Corresponding shares of two secrets can be added locally.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-12-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"用玩具向量逐方相加並重建核對。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Add toy share vectors by party and verify reconstruction. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「秘密加法」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for secret addition?","options":["秘密加法必須先公開兩個明文。","先把「秘密加法」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。","用玩具向量逐方相加並重建核對。"],"optionsEn":["Secret addition requires revealing both plaintexts.","Tune the displayed secret addition result to the expected value and count that agreement as independent validation.","Add toy share vectors by party and verify reconstruction."],"answer":2,"explanation":"兩個秘密的對應分享可區域性相加。 用玩具向量逐方相加並重建核對。 因此「秘密加法必須先公開兩個明文。」混淆了本單元必須分開檢查的條件。","explanationEn":"Corresponding shares of two secrets can be added locally. Add toy share vectors by party and verify reconstruction. The alternative \"Secret addition requires revealing both plaintexts.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-13","order":5,"sequence":13,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-12"],"title":"秘密乘法：原理與架構","titleEn":"Secret multiplication: principles and architecture","objective":"以「秘密乘法」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for secret multiplication.","instruction":"先觀察師傅的「秘密乘法」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：區域性分享相乘通常缺少跨分享交叉項。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「展開兩個分享和的乘積找出交叉項。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for secret multiplication. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Local share products generally miss cross-share terms. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Expand share-sum products and locate cross terms. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"展開兩個分享和的乘積找出交叉項。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Expand share-sum products and locate cross terms. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：對應分享相乘就必然得到正確乘積分享。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Multiplying corresponding shares always yields correct product shares. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「秘密乘法」兩情境架構圖、假設與可反駁預測，並說明「展開兩個分享和的乘積找出交叉項。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for secret multiplication; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-13-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"區域性分享相乘通常缺少跨分享交叉項。","textEn":"Local share products generally miss cross-share terms.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-13-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"展開兩個分享和的乘積找出交叉項。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Expand share-sum products and locate cross terms. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「秘密乘法」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for secret multiplication?","options":["區域性分享相乘通常缺少跨分享交叉項。","對應分享相乘就必然得到正確乘積分享。","只要一次輸出符合預期，就能推定「秘密乘法」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Local share products generally miss cross-share terms.","Multiplying corresponding shares always yields correct product shares.","One matching output proves secret multiplication for all sizes, versions and failure conditions."],"answer":0,"explanation":"區域性分享相乘通常缺少跨分享交叉項。 展開兩個分享和的乘積找出交叉項。 因此「對應分享相乘就必然得到正確乘積分享。」混淆了本單元必須分開檢查的條件。","explanationEn":"Local share products generally miss cross-share terms. Expand share-sum products and locate cross terms. The alternative \"Multiplying corresponding shares always yields correct product shares.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-14","order":6,"sequence":14,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-13"],"title":"秘密乘法：實驗與證據","titleEn":"Secret multiplication: experiments and evidence","objective":"以「秘密乘法」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for secret multiplication.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「展開兩個分享和的乘積找出交叉項。」；將結果與「區域性分享相乘通常缺少跨分享交叉項。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Expand share-sum products and locate cross terms. Compare results against: Local share products generally miss cross-share terms. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"展開兩個分享和的乘積找出交叉項。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Expand share-sum products and locate cross terms. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：對應分享相乘就必然得到正確乘積分享。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Multiplying corresponding shares always yields correct product shares. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「秘密乘法」實驗輸出、基準差異、誤判排除與限用條件；解釋「對應分享相乘就必然得到正確乘積分享。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for secret multiplication; explain why this claim fails: Multiplying corresponding shares always yields correct product shares.","knowledge":[{"id":"a375-v11-14-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"區域性分享相乘通常缺少跨分享交叉項。","textEn":"Local share products generally miss cross-share terms.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-14-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"展開兩個分享和的乘積找出交叉項。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Expand share-sum products and locate cross terms. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「秘密乘法」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for secret multiplication?","options":["對應分享相乘就必然得到正確乘積分享。","展開兩個分享和的乘積找出交叉項。","先把「秘密乘法」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Multiplying corresponding shares always yields correct product shares.","Expand share-sum products and locate cross terms.","Tune the displayed secret multiplication result to the expected value and count that agreement as independent validation."],"answer":1,"explanation":"區域性分享相乘通常缺少跨分享交叉項。 展開兩個分享和的乘積找出交叉項。 因此「對應分享相乘就必然得到正確乘積分享。」混淆了本單元必須分開檢查的條件。","explanationEn":"Local share products generally miss cross-share terms. Expand share-sum products and locate cross terms. The alternative \"Multiplying corresponding shares always yields correct product shares.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-15","order":7,"sequence":15,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-14"],"title":"預處理材料：原理與架構","titleEn":"Preprocessing material: principles and architecture","objective":"以「預處理材料」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for preprocessing material.","instruction":"先觀察師傅的「預處理材料」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：乘法三元組等材料必須與協議安全假設相容。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「以符號流程標示離線材料和線上使用。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for preprocessing material. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Multiplication triples must match protocol security assumptions. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Mark offline material and online consumption symbolically. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"以符號流程標示離線材料和線上使用。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Mark offline material and online consumption symbolically. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：同一個三元組可以無限重用。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: One multiplication triple can be reused indefinitely. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「預處理材料」兩情境架構圖、假設與可反駁預測，並說明「以符號流程標示離線材料和線上使用。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for preprocessing material; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-15-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"乘法三元組等材料必須與協議安全假設相容。","textEn":"Multiplication triples must match protocol security assumptions.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-15-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"以符號流程標示離線材料和線上使用。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Mark offline material and online consumption symbolically. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「預處理材料」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for preprocessing material?","options":["同一個三元組可以無限重用。","只要一次輸出符合預期，就能推定「預處理材料」對所有資料量、版本與故障條件都成立。","乘法三元組等材料必須與協議安全假設相容。"],"optionsEn":["One multiplication triple can be reused indefinitely.","One matching output proves preprocessing material for all sizes, versions and failure conditions.","Multiplication triples must match protocol security assumptions."],"answer":2,"explanation":"乘法三元組等材料必須與協議安全假設相容。 以符號流程標示離線材料和線上使用。 因此「同一個三元組可以無限重用。」混淆了本單元必須分開檢查的條件。","explanationEn":"Multiplication triples must match protocol security assumptions. Mark offline material and online consumption symbolically. The alternative \"One multiplication triple can be reused indefinitely.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-16","order":8,"sequence":16,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-15"],"title":"預處理材料：實驗與證據","titleEn":"Preprocessing material: experiments and evidence","objective":"以「預處理材料」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for preprocessing material.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「以符號流程標示離線材料和線上使用。」；將結果與「乘法三元組等材料必須與協議安全假設相容。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Mark offline material and online consumption symbolically. Compare results against: Multiplication triples must match protocol security assumptions. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"以符號流程標示離線材料和線上使用。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Mark offline material and online consumption symbolically. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：同一個三元組可以無限重用。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: One multiplication triple can be reused indefinitely. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「預處理材料」實驗輸出、基準差異、誤判排除與限用條件；解釋「同一個三元組可以無限重用。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for preprocessing material; explain why this claim fails: One multiplication triple can be reused indefinitely.","knowledge":[{"id":"a375-v11-16-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"乘法三元組等材料必須與協議安全假設相容。","textEn":"Multiplication triples must match protocol security assumptions.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-16-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"以符號流程標示離線材料和線上使用。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Mark offline material and online consumption symbolically. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「預處理材料」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for preprocessing material?","options":["以符號流程標示離線材料和線上使用。","同一個三元組可以無限重用。","先把「預處理材料」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Mark offline material and online consumption symbolically.","One multiplication triple can be reused indefinitely.","Tune the displayed preprocessing material result to the expected value and count that agreement as independent validation."],"answer":0,"explanation":"乘法三元組等材料必須與協議安全假設相容。 以符號流程標示離線材料和線上使用。 因此「同一個三元組可以無限重用。」混淆了本單元必須分開檢查的條件。","explanationEn":"Multiplication triples must match protocol security assumptions. Mark offline material and online consumption symbolically. The alternative \"One multiplication triple can be reused indefinitely.\" conflates conditions that must be checked separately."}}]},{"id":"a375-v11-stage03","order":3,"title":"協議與故障","titleEn":"Protocols and failures","description":"四個技術單元依序完成「協議與故障」的架構與證據，共八步可分別儲存的本地科教實作。","descriptionEn":"Four technical units develop protocols and failures through eight separately saved local educational tasks.","steps":[{"id":"a375-v11-17","order":1,"sequence":17,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-16"],"title":"比較運算：原理與架構","titleEn":"Comparison circuits: principles and architecture","objective":"以「比較運算」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for comparison circuits.","instruction":"先觀察師傅的「比較運算」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：秘密比較需不同於普通公開分支的協議。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「對玩具最大值畫不公開中間比較的電路。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for comparison circuits. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Secret comparisons need protocols unlike public branches. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Draw a toy maximum circuit without revealing intermediate comparisons. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"對玩具最大值畫不公開中間比較的電路。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Draw a toy maximum circuit without revealing intermediate comparisons. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：秘密值可直接在公開 if 裡分支且不洩漏。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Public branching on a secret reveals nothing. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「比較運算」兩情境架構圖、假設與可反駁預測，並說明「對玩具最大值畫不公開中間比較的電路。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for comparison circuits; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-17-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"秘密比較需不同於普通公開分支的協議。","textEn":"Secret comparisons need protocols unlike public branches.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-17-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"對玩具最大值畫不公開中間比較的電路。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Draw a toy maximum circuit without revealing intermediate comparisons. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「比較運算」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for comparison circuits?","options":["秘密值可直接在公開 if 裡分支且不洩漏。","秘密比較需不同於普通公開分支的協議。","只要一次輸出符合預期，就能推定「比較運算」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Public branching on a secret reveals nothing.","Secret comparisons need protocols unlike public branches.","One matching output proves comparison circuits for all sizes, versions and failure conditions."],"answer":1,"explanation":"秘密比較需不同於普通公開分支的協議。 對玩具最大值畫不公開中間比較的電路。 因此「秘密值可直接在公開 if 裡分支且不洩漏。」混淆了本單元必須分開檢查的條件。","explanationEn":"Secret comparisons need protocols unlike public branches. Draw a toy maximum circuit without revealing intermediate comparisons. The alternative \"Public branching on a secret reveals nothing.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-18","order":2,"sequence":18,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-17"],"title":"比較運算：實驗與證據","titleEn":"Comparison circuits: experiments and evidence","objective":"以「比較運算」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for comparison circuits.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「對玩具最大值畫不公開中間比較的電路。」；將結果與「秘密比較需不同於普通公開分支的協議。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Draw a toy maximum circuit without revealing intermediate comparisons. Compare results against: Secret comparisons need protocols unlike public branches. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"對玩具最大值畫不公開中間比較的電路。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Draw a toy maximum circuit without revealing intermediate comparisons. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：秘密值可直接在公開 if 裡分支且不洩漏。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Public branching on a secret reveals nothing. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「比較運算」實驗輸出、基準差異、誤判排除與限用條件；解釋「秘密值可直接在公開 if 裡分支且不洩漏。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for comparison circuits; explain why this claim fails: Public branching on a secret reveals nothing.","knowledge":[{"id":"a375-v11-18-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"秘密比較需不同於普通公開分支的協議。","textEn":"Secret comparisons need protocols unlike public branches.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-18-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"對玩具最大值畫不公開中間比較的電路。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Draw a toy maximum circuit without revealing intermediate comparisons. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「比較運算」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for comparison circuits?","options":["秘密值可直接在公開 if 裡分支且不洩漏。","先把「比較運算」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。","對玩具最大值畫不公開中間比較的電路。"],"optionsEn":["Public branching on a secret reveals nothing.","Tune the displayed comparison circuits result to the expected value and count that agreement as independent validation.","Draw a toy maximum circuit without revealing intermediate comparisons."],"answer":2,"explanation":"秘密比較需不同於普通公開分支的協議。 對玩具最大值畫不公開中間比較的電路。 因此「秘密值可直接在公開 if 裡分支且不洩漏。」混淆了本單元必須分開檢查的條件。","explanationEn":"Secret comparisons need protocols unlike public branches. Draw a toy maximum circuit without revealing intermediate comparisons. The alternative \"Public branching on a secret reveals nothing.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-19","order":3,"sequence":19,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-18"],"title":"定點數值：原理與架構","titleEn":"Fixed-point numbers: principles and architecture","objective":"以「定點數值」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for fixed-point numbers.","instruction":"先觀察師傅的「定點數值」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：定點縮放與截斷影響範圍及誤差。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「以合成小數比較不同縮放因子的誤差。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for fixed-point numbers. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Fixed-point scaling and truncation affect range and error. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Compare scaling-factor errors for synthetic decimals. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"以合成小數比較不同縮放因子的誤差。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Compare scaling-factor errors for synthetic decimals. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：有限環可無需編碼直接存任意實數。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Finite rings directly store arbitrary reals without encoding. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「定點數值」兩情境架構圖、假設與可反駁預測，並說明「以合成小數比較不同縮放因子的誤差。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for fixed-point numbers; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-19-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"定點縮放與截斷影響範圍及誤差。","textEn":"Fixed-point scaling and truncation affect range and error.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-19-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"以合成小數比較不同縮放因子的誤差。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Compare scaling-factor errors for synthetic decimals. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「定點數值」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for fixed-point numbers?","options":["定點縮放與截斷影響範圍及誤差。","有限環可無需編碼直接存任意實數。","只要一次輸出符合預期，就能推定「定點數值」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Fixed-point scaling and truncation affect range and error.","Finite rings directly store arbitrary reals without encoding.","One matching output proves fixed-point numbers for all sizes, versions and failure conditions."],"answer":0,"explanation":"定點縮放與截斷影響範圍及誤差。 以合成小數比較不同縮放因子的誤差。 因此「有限環可無需編碼直接存任意實數。」混淆了本單元必須分開檢查的條件。","explanationEn":"Fixed-point scaling and truncation affect range and error. Compare scaling-factor errors for synthetic decimals. The alternative \"Finite rings directly store arbitrary reals without encoding.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-20","order":4,"sequence":20,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-19"],"title":"定點數值：實驗與證據","titleEn":"Fixed-point numbers: experiments and evidence","objective":"以「定點數值」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for fixed-point numbers.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「以合成小數比較不同縮放因子的誤差。」；將結果與「定點縮放與截斷影響範圍及誤差。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Compare scaling-factor errors for synthetic decimals. Compare results against: Fixed-point scaling and truncation affect range and error. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"以合成小數比較不同縮放因子的誤差。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Compare scaling-factor errors for synthetic decimals. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：有限環可無需編碼直接存任意實數。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Finite rings directly store arbitrary reals without encoding. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「定點數值」實驗輸出、基準差異、誤判排除與限用條件；解釋「有限環可無需編碼直接存任意實數。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for fixed-point numbers; explain why this claim fails: Finite rings directly store arbitrary reals without encoding.","knowledge":[{"id":"a375-v11-20-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"定點縮放與截斷影響範圍及誤差。","textEn":"Fixed-point scaling and truncation affect range and error.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-20-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"以合成小數比較不同縮放因子的誤差。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Compare scaling-factor errors for synthetic decimals. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「定點數值」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for fixed-point numbers?","options":["有限環可無需編碼直接存任意實數。","以合成小數比較不同縮放因子的誤差。","先把「定點數值」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Finite rings directly store arbitrary reals without encoding.","Compare scaling-factor errors for synthetic decimals.","Tune the displayed fixed-point numbers result to the expected value and count that agreement as independent validation."],"answer":1,"explanation":"定點縮放與截斷影響範圍及誤差。 以合成小數比較不同縮放因子的誤差。 因此「有限環可無需編碼直接存任意實數。」混淆了本單元必須分開檢查的條件。","explanationEn":"Fixed-point scaling and truncation affect range and error. Compare scaling-factor errors for synthetic decimals. The alternative \"Finite rings directly store arbitrary reals without encoding.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-21","order":5,"sequence":21,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-20"],"title":"通訊輪次：原理與架構","titleEn":"Communication rounds: principles and architecture","objective":"以「通訊輪次」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for communication rounds.","instruction":"先觀察師傅的「通訊輪次」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：網路延遲對多輪依賴協議的成本影響大。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「比較 10 與 100 輪在假想 RTT 下的下限。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for communication rounds. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Network latency strongly affects dependent multiround protocols. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Compare latency bounds for 10 and 100 rounds under assumed RTT. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"比較 10 與 100 輪在假想 RTT 下的下限。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Compare latency bounds for 10 and 100 rounds under assumed RTT. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：吞吐相同的網路對多輪協議完全等價。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Equal-throughput networks are equivalent for multiround protocols. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「通訊輪次」兩情境架構圖、假設與可反駁預測，並說明「比較 10 與 100 輪在假想 RTT 下的下限。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for communication rounds; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-21-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"網路延遲對多輪依賴協議的成本影響大。","textEn":"Network latency strongly affects dependent multiround protocols.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-21-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"比較 10 與 100 輪在假想 RTT 下的下限。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Compare latency bounds for 10 and 100 rounds under assumed RTT. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「通訊輪次」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for communication rounds?","options":["吞吐相同的網路對多輪協議完全等價。","只要一次輸出符合預期，就能推定「通訊輪次」對所有資料量、版本與故障條件都成立。","網路延遲對多輪依賴協議的成本影響大。"],"optionsEn":["Equal-throughput networks are equivalent for multiround protocols.","One matching output proves communication rounds for all sizes, versions and failure conditions.","Network latency strongly affects dependent multiround protocols."],"answer":2,"explanation":"網路延遲對多輪依賴協議的成本影響大。 比較 10 與 100 輪在假想 RTT 下的下限。 因此「吞吐相同的網路對多輪協議完全等價。」混淆了本單元必須分開檢查的條件。","explanationEn":"Network latency strongly affects dependent multiround protocols. Compare latency bounds for 10 and 100 rounds under assumed RTT. The alternative \"Equal-throughput networks are equivalent for multiround protocols.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-22","order":6,"sequence":22,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-21"],"title":"通訊輪次：實驗與證據","titleEn":"Communication rounds: experiments and evidence","objective":"以「通訊輪次」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for communication rounds.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「比較 10 與 100 輪在假想 RTT 下的下限。」；將結果與「網路延遲對多輪依賴協議的成本影響大。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Compare latency bounds for 10 and 100 rounds under assumed RTT. Compare results against: Network latency strongly affects dependent multiround protocols. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"比較 10 與 100 輪在假想 RTT 下的下限。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Compare latency bounds for 10 and 100 rounds under assumed RTT. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：吞吐相同的網路對多輪協議完全等價。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Equal-throughput networks are equivalent for multiround protocols. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「通訊輪次」實驗輸出、基準差異、誤判排除與限用條件；解釋「吞吐相同的網路對多輪協議完全等價。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for communication rounds; explain why this claim fails: Equal-throughput networks are equivalent for multiround protocols.","knowledge":[{"id":"a375-v11-22-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"網路延遲對多輪依賴協議的成本影響大。","textEn":"Network latency strongly affects dependent multiround protocols.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-22-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"比較 10 與 100 輪在假想 RTT 下的下限。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Compare latency bounds for 10 and 100 rounds under assumed RTT. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「通訊輪次」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for communication rounds?","options":["比較 10 與 100 輪在假想 RTT 下的下限。","吞吐相同的網路對多輪協議完全等價。","先把「通訊輪次」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Compare latency bounds for 10 and 100 rounds under assumed RTT.","Equal-throughput networks are equivalent for multiround protocols.","Tune the displayed communication rounds result to the expected value and count that agreement as independent validation."],"answer":0,"explanation":"網路延遲對多輪依賴協議的成本影響大。 比較 10 與 100 輪在假想 RTT 下的下限。 因此「吞吐相同的網路對多輪協議完全等價。」混淆了本單元必須分開檢查的條件。","explanationEn":"Network latency strongly affects dependent multiround protocols. Compare latency bounds for 10 and 100 rounds under assumed RTT. The alternative \"Equal-throughput networks are equivalent for multiround protocols.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-23","order":7,"sequence":23,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-22"],"title":"認證檢查：原理與架構","titleEn":"Authentication checks: principles and architecture","objective":"以「認證檢查」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for authentication checks.","instruction":"先觀察師傅的「認證檢查」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：惡意安全的完整性檢查與隱私是不同性質。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「在符號記錄區分分享機密與訊息認證。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for authentication checks. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Malicious-security integrity checks differ from privacy. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Separate share confidentiality and message authentication symbolically. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"在符號記錄區分分享機密與訊息認證。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Separate share confidentiality and message authentication symbolically. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：資料被分享就自動能檢測所有篡改。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Sharing data automatically detects every alteration. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「認證檢查」兩情境架構圖、假設與可反駁預測，並說明「在符號記錄區分分享機密與訊息認證。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for authentication checks; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-23-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"惡意安全的完整性檢查與隱私是不同性質。","textEn":"Malicious-security integrity checks differ from privacy.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-23-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"在符號記錄區分分享機密與訊息認證。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Separate share confidentiality and message authentication symbolically. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「認證檢查」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for authentication checks?","options":["資料被分享就自動能檢測所有篡改。","惡意安全的完整性檢查與隱私是不同性質。","只要一次輸出符合預期，就能推定「認證檢查」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Sharing data automatically detects every alteration.","Malicious-security integrity checks differ from privacy.","One matching output proves authentication checks for all sizes, versions and failure conditions."],"answer":1,"explanation":"惡意安全的完整性檢查與隱私是不同性質。 在符號記錄區分分享機密與訊息認證。 因此「資料被分享就自動能檢測所有篡改。」混淆了本單元必須分開檢查的條件。","explanationEn":"Malicious-security integrity checks differ from privacy. Separate share confidentiality and message authentication symbolically. The alternative \"Sharing data automatically detects every alteration.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-24","order":8,"sequence":24,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-23"],"title":"認證檢查：實驗與證據","titleEn":"Authentication checks: experiments and evidence","objective":"以「認證檢查」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for authentication checks.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「在符號記錄區分分享機密與訊息認證。」；將結果與「惡意安全的完整性檢查與隱私是不同性質。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Separate share confidentiality and message authentication symbolically. Compare results against: Malicious-security integrity checks differ from privacy. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"在符號記錄區分分享機密與訊息認證。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Separate share confidentiality and message authentication symbolically. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：資料被分享就自動能檢測所有篡改。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Sharing data automatically detects every alteration. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「認證檢查」實驗輸出、基準差異、誤判排除與限用條件；解釋「資料被分享就自動能檢測所有篡改。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for authentication checks; explain why this claim fails: Sharing data automatically detects every alteration.","knowledge":[{"id":"a375-v11-24-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"惡意安全的完整性檢查與隱私是不同性質。","textEn":"Malicious-security integrity checks differ from privacy.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-24-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"在符號記錄區分分享機密與訊息認證。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Separate share confidentiality and message authentication symbolically. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「認證檢查」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for authentication checks?","options":["資料被分享就自動能檢測所有篡改。","先把「認證檢查」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。","在符號記錄區分分享機密與訊息認證。"],"optionsEn":["Sharing data automatically detects every alteration.","Tune the displayed authentication checks result to the expected value and count that agreement as independent validation.","Separate share confidentiality and message authentication symbolically."],"answer":2,"explanation":"惡意安全的完整性檢查與隱私是不同性質。 在符號記錄區分分享機密與訊息認證。 因此「資料被分享就自動能檢測所有篡改。」混淆了本單元必須分開檢查的條件。","explanationEn":"Malicious-security integrity checks differ from privacy. Separate share confidentiality and message authentication symbolically. The alternative \"Sharing data automatically detects every alteration.\" conflates conditions that must be checked separately."}}]},{"id":"a375-v11-stage04","order":4,"title":"輸出與驗證","titleEn":"Outputs and validation","description":"四個技術單元依序完成「輸出與驗證」的架構與證據，共八步可分別儲存的本地科教實作。","descriptionEn":"Four technical units develop outputs and validation through eight separately saved local educational tasks.","steps":[{"id":"a375-v11-25","order":1,"sequence":25,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-24"],"title":"退出與終止：原理與架構","titleEn":"Dropout and abort: principles and architecture","objective":"以「退出與終止」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for dropout and abort.","instruction":"先觀察師傅的「退出與終止」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：某些協議允許中止但不保證每方獲得輸出。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「用紙上狀態圖分析一方離開。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for dropout and abort. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Some protocols permit abort without guaranteeing everyone an output. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Analyze one party leaving with a paper state diagram. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"用紙上狀態圖分析一方離開。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Analyze one party leaving with a paper state diagram. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：安全協議必定提供公平與不中止。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Secure protocols always guarantee fairness and no abort. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「退出與終止」兩情境架構圖、假設與可反駁預測，並說明「用紙上狀態圖分析一方離開。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for dropout and abort; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-25-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"某些協議允許中止但不保證每方獲得輸出。","textEn":"Some protocols permit abort without guaranteeing everyone an output.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-25-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"用紙上狀態圖分析一方離開。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Analyze one party leaving with a paper state diagram. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「退出與終止」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for dropout and abort?","options":["某些協議允許中止但不保證每方獲得輸出。","安全協議必定提供公平與不中止。","只要一次輸出符合預期，就能推定「退出與終止」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Some protocols permit abort without guaranteeing everyone an output.","Secure protocols always guarantee fairness and no abort.","One matching output proves dropout and abort for all sizes, versions and failure conditions."],"answer":0,"explanation":"某些協議允許中止但不保證每方獲得輸出。 用紙上狀態圖分析一方離開。 因此「安全協議必定提供公平與不中止。」混淆了本單元必須分開檢查的條件。","explanationEn":"Some protocols permit abort without guaranteeing everyone an output. Analyze one party leaving with a paper state diagram. The alternative \"Secure protocols always guarantee fairness and no abort.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-26","order":2,"sequence":26,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-25"],"title":"退出與終止：實驗與證據","titleEn":"Dropout and abort: experiments and evidence","objective":"以「退出與終止」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for dropout and abort.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「用紙上狀態圖分析一方離開。」；將結果與「某些協議允許中止但不保證每方獲得輸出。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Analyze one party leaving with a paper state diagram. Compare results against: Some protocols permit abort without guaranteeing everyone an output. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"用紙上狀態圖分析一方離開。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Analyze one party leaving with a paper state diagram. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：安全協議必定提供公平與不中止。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Secure protocols always guarantee fairness and no abort. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「退出與終止」實驗輸出、基準差異、誤判排除與限用條件；解釋「安全協議必定提供公平與不中止。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for dropout and abort; explain why this claim fails: Secure protocols always guarantee fairness and no abort.","knowledge":[{"id":"a375-v11-26-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"某些協議允許中止但不保證每方獲得輸出。","textEn":"Some protocols permit abort without guaranteeing everyone an output.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-26-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"用紙上狀態圖分析一方離開。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Analyze one party leaving with a paper state diagram. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「退出與終止」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for dropout and abort?","options":["安全協議必定提供公平與不中止。","用紙上狀態圖分析一方離開。","先把「退出與終止」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Secure protocols always guarantee fairness and no abort.","Analyze one party leaving with a paper state diagram.","Tune the displayed dropout and abort result to the expected value and count that agreement as independent validation."],"answer":1,"explanation":"某些協議允許中止但不保證每方獲得輸出。 用紙上狀態圖分析一方離開。 因此「安全協議必定提供公平與不中止。」混淆了本單元必須分開檢查的條件。","explanationEn":"Some protocols permit abort without guaranteeing everyone an output. Analyze one party leaving with a paper state diagram. The alternative \"Secure protocols always guarantee fairness and no abort.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-27","order":3,"sequence":27,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-26"],"title":"輸出洩漏：原理與架構","titleEn":"Output disclosure: principles and architecture","objective":"以「輸出洩漏」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for output disclosure.","instruction":"先觀察師傅的「輸出洩漏」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：合法輸出的統計仍可能揭露輸入資訊。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「比較總和、均值與每個輸入輸出。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for output disclosure. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Allowed output statistics may disclose input information. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Compare totals, means and individual-input outputs. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"比較總和、均值與每個輸入輸出。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Compare totals, means and individual-input outputs. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：MPC 輸出無需任何披露風險評估。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: MPC outputs need no disclosure-risk review. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「輸出洩漏」兩情境架構圖、假設與可反駁預測，並說明「比較總和、均值與每個輸入輸出。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for output disclosure; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-27-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"合法輸出的統計仍可能揭露輸入資訊。","textEn":"Allowed output statistics may disclose input information.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-27-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"比較總和、均值與每個輸入輸出。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Compare totals, means and individual-input outputs. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「輸出洩漏」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for output disclosure?","options":["MPC 輸出無需任何披露風險評估。","只要一次輸出符合預期，就能推定「輸出洩漏」對所有資料量、版本與故障條件都成立。","合法輸出的統計仍可能揭露輸入資訊。"],"optionsEn":["MPC outputs need no disclosure-risk review.","One matching output proves output disclosure for all sizes, versions and failure conditions.","Allowed output statistics may disclose input information."],"answer":2,"explanation":"合法輸出的統計仍可能揭露輸入資訊。 比較總和、均值與每個輸入輸出。 因此「MPC 輸出無需任何披露風險評估。」混淆了本單元必須分開檢查的條件。","explanationEn":"Allowed output statistics may disclose input information. Compare totals, means and individual-input outputs. The alternative \"MPC outputs need no disclosure-risk review.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-28","order":4,"sequence":28,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-27"],"title":"輸出洩漏：實驗與證據","titleEn":"Output disclosure: experiments and evidence","objective":"以「輸出洩漏」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for output disclosure.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「比較總和、均值與每個輸入輸出。」；將結果與「合法輸出的統計仍可能揭露輸入資訊。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Compare totals, means and individual-input outputs. Compare results against: Allowed output statistics may disclose input information. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"比較總和、均值與每個輸入輸出。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Compare totals, means and individual-input outputs. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：MPC 輸出無需任何披露風險評估。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: MPC outputs need no disclosure-risk review. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「輸出洩漏」實驗輸出、基準差異、誤判排除與限用條件；解釋「MPC 輸出無需任何披露風險評估。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for output disclosure; explain why this claim fails: MPC outputs need no disclosure-risk review.","knowledge":[{"id":"a375-v11-28-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"合法輸出的統計仍可能揭露輸入資訊。","textEn":"Allowed output statistics may disclose input information.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-28-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"比較總和、均值與每個輸入輸出。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Compare totals, means and individual-input outputs. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「輸出洩漏」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for output disclosure?","options":["比較總和、均值與每個輸入輸出。","MPC 輸出無需任何披露風險評估。","先把「輸出洩漏」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Compare totals, means and individual-input outputs.","MPC outputs need no disclosure-risk review.","Tune the displayed output disclosure result to the expected value and count that agreement as independent validation."],"answer":0,"explanation":"合法輸出的統計仍可能揭露輸入資訊。 比較總和、均值與每個輸入輸出。 因此「MPC 輸出無需任何披露風險評估。」混淆了本單元必須分開檢查的條件。","explanationEn":"Allowed output statistics may disclose input information. Compare totals, means and individual-input outputs. The alternative \"MPC outputs need no disclosure-risk review.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-29","order":5,"sequence":29,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-28"],"title":"成本驗證：原理與架構","titleEn":"Cost validation: principles and architecture","objective":"以「成本驗證」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for cost validation.","instruction":"先觀察師傅的「成本驗證」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：協議、參與數與資料量需一起報告。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「記錄玩具基準的輪數、位元組和版本。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for cost validation. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Protocol, party count and data size must be reported together. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Record toy benchmark rounds, bytes and versions. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"記錄玩具基準的輪數、位元組和版本。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Record toy benchmark rounds, bytes and versions. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：只報告每秒運算元就足以比較所有 MPC。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Operations per second suffice to compare all MPC systems. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「成本驗證」兩情境架構圖、假設與可反駁預測，並說明「記錄玩具基準的輪數、位元組和版本。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for cost validation; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-29-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"協議、參與數與資料量需一起報告。","textEn":"Protocol, party count and data size must be reported together.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-29-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"記錄玩具基準的輪數、位元組和版本。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Record toy benchmark rounds, bytes and versions. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「成本驗證」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for cost validation?","options":["只報告每秒運算元就足以比較所有 MPC。","協議、參與數與資料量需一起報告。","只要一次輸出符合預期，就能推定「成本驗證」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Operations per second suffice to compare all MPC systems.","Protocol, party count and data size must be reported together.","One matching output proves cost validation for all sizes, versions and failure conditions."],"answer":1,"explanation":"協議、參與數與資料量需一起報告。 記錄玩具基準的輪數、位元組和版本。 因此「只報告每秒運算元就足以比較所有 MPC。」混淆了本單元必須分開檢查的條件。","explanationEn":"Protocol, party count and data size must be reported together. Record toy benchmark rounds, bytes and versions. The alternative \"Operations per second suffice to compare all MPC systems.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-30","order":6,"sequence":30,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-29"],"title":"成本驗證：實驗與證據","titleEn":"Cost validation: experiments and evidence","objective":"以「成本驗證」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for cost validation.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「記錄玩具基準的輪數、位元組和版本。」；將結果與「協議、參與數與資料量需一起報告。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Record toy benchmark rounds, bytes and versions. Compare results against: Protocol, party count and data size must be reported together. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"記錄玩具基準的輪數、位元組和版本。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Record toy benchmark rounds, bytes and versions. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：只報告每秒運算元就足以比較所有 MPC。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Operations per second suffice to compare all MPC systems. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「成本驗證」實驗輸出、基準差異、誤判排除與限用條件；解釋「只報告每秒運算元就足以比較所有 MPC。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for cost validation; explain why this claim fails: Operations per second suffice to compare all MPC systems.","knowledge":[{"id":"a375-v11-30-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"協議、參與數與資料量需一起報告。","textEn":"Protocol, party count and data size must be reported together.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-30-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"記錄玩具基準的輪數、位元組和版本。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Record toy benchmark rounds, bytes and versions. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"}],"quiz":{"question":"審查「成本驗證」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for cost validation?","options":["只報告每秒運算元就足以比較所有 MPC。","先把「成本驗證」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。","記錄玩具基準的輪數、位元組和版本。"],"optionsEn":["Operations per second suffice to compare all MPC systems.","Tune the displayed cost validation result to the expected value and count that agreement as independent validation.","Record toy benchmark rounds, bytes and versions."],"answer":2,"explanation":"協議、參與數與資料量需一起報告。 記錄玩具基準的輪數、位元組和版本。 因此「只報告每秒運算元就足以比較所有 MPC。」混淆了本單元必須分開檢查的條件。","explanationEn":"Protocol, party count and data size must be reported together. Record toy benchmark rounds, bytes and versions. The alternative \"Operations per second suffice to compare all MPC systems.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-31","order":7,"sequence":31,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-30"],"title":"部署分離：原理與架構","titleEn":"Deployment separation: principles and architecture","objective":"以「部署分離」建立原理、介面與可反駁模型。","objectiveEn":"Build principles, interfaces and a falsifiable model for deployment separation.","instruction":"先觀察師傅的「部署分離」示意，依序辨認輸入、狀態、輸出與信任或數值邊界，再在學徒工作臺排出資料／元件路徑。原理：模擬三個程序不等於真實獨立信任域。 使用自行生成的小資料、紙上圖或本地玩具程式建立基準與一項受控變更；先寫下可觀察預測，再設計「分開標示本地驗證與實際信任部署要求。」的驗證。記錄單位、版本、假設與未知量，不把示意模型當真實裝置或服務。","instructionEn":"Watch the mentor demonstration for deployment separation. Identify inputs, state, outputs and trust/numerical boundaries, then arrange the data/component flow in the apprentice workspace. Principle: Three simulated processes are not independent trust domains. Use self-generated small data, paper diagrams or a local toy program to create a baseline and one controlled change. State an observable prediction before planning this check: Distinguish local validation from actual trust-domain requirements. Record units, versions, assumptions and unknowns; the model is not real equipment or service.","observation":"分開標示本地驗證與實際信任部署要求。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Distinguish local validation from actual trust-domain requirements. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：同機三個程式證明了跨機構不串通。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Three same-host processes prove institutional noncollusion. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「部署分離」兩情境架構圖、假設與可反駁預測，並說明「分開標示本地驗證與實際信任部署要求。」如何辨別它們。","checkEn":"Submit a two-case architecture, assumptions and falsifiable prediction for deployment separation; explain how the proposed evidence discriminates the cases.","knowledge":[{"id":"a375-v11-31-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"模擬三個程序不等於真實獨立信任域。","textEn":"Three simulated processes are not independent trust domains.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-31-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"分開標示本地驗證與實際信任部署要求。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Distinguish local validation from actual trust-domain requirements. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"},{"id":"a375-v11-31-k3","title":"本課量化算例","titleEn":"Course quantitative example","text":"玩具模環 Z₁₇ 將秘密 s=9 分享為 4、7、15，因為 (4+7+15) mod17=9。每個分享若按正確隨機協議產生可隱藏原值；此固定例子不構成安全實作。加上公開值 3 後可只改一個分享為 7，和變為 12。","textEn":"Toy shares 4,7,15 in Z17 sum to secret 9. Secure hiding requires a correct randomized protocol; these fixed numbers are not a secure implementation. Adding public 3 to one share changes the reconstructed sum to 12.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"審查「部署分離」的原理與架構時，哪個說法成立？","questionEn":"Which principle/architecture claim is justified for deployment separation?","options":["模擬三個程序不等於真實獨立信任域。","同機三個程式證明了跨機構不串通。","只要一次輸出符合預期，就能推定「部署分離」對所有資料量、版本與故障條件都成立。"],"optionsEn":["Three simulated processes are not independent trust domains.","Three same-host processes prove institutional noncollusion.","One matching output proves deployment separation for all sizes, versions and failure conditions."],"answer":0,"explanation":"模擬三個程序不等於真實獨立信任域。 分開標示本地驗證與實際信任部署要求。 因此「同機三個程式證明了跨機構不串通。」混淆了本單元必須分開檢查的條件。","explanationEn":"Three simulated processes are not independent trust domains. Distinguish local validation from actual trust-domain requirements. The alternative \"Three same-host processes prove institutional noncollusion.\" conflates conditions that must be checked separately."}},{"id":"a375-v11-32","order":8,"sequence":32,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11c-mpc","v11c-mpcsrc"],"prerequisiteIds":["a375-v11-31"],"title":"部署分離：實驗與證據","titleEn":"Deployment separation: experiments and evidence","objective":"以「部署分離」建立可重算實驗、錯誤辨識與驗收證據。","objectiveEn":"Build reproducible experiments, diagnosis and acceptance evidence for deployment separation.","instruction":"重播本單元示意後，僅在自製資料、副本或本地合成環境驗證，不連線真實目標、不取得旁人資料。實作：「分開標示本地驗證與實際信任部署要求。」；將結果與「模擬三個程序不等於真實獨立信任域。」逐項對照。保留基準和變更後輸出，先列至少兩個可能造成差異的原因，再用版本、單位、誤差或信任邊界排除其中一項。未有實測的數值須明寫為假想值。最後寫出透過／保留的理由和仍待驗證條件。","instructionEn":"Replay the unit, then validate only self-made data, copies or a local synthetic environment; do not connect to real targets or collect other people's data. Exercise: Distinguish local validation from actual trust-domain requirements. Compare results against: Three simulated processes are not independent trust domains. Preserve baseline and changed outputs. List at least two competing causes and discriminate one using versions, units, errors or trust boundaries. Label unmeasured values hypothetical. Document pass/hold reasons and remaining conditions.","observation":"分開標示本地驗證與實際信任部署要求。 核對上述原理的適用範圍並記錄不符合預期之處。","observationEn":"Distinguish local validation from actual trust-domain requirements. Check the scope of the stated principle and record departures from expectations.","failure":"常見誤判：同機三個程式證明了跨機構不串通。 應檢查資料版本、單位、信任邊界與可區分原因的證據。","failureEn":"Common misconception: Three same-host processes prove institutional noncollusion. Check versions, units, trust boundaries and discriminating evidence.","check":"提交「部署分離」實驗輸出、基準差異、誤判排除與限用條件；解釋「同機三個程式證明了跨機構不串通。」為何不成立。","checkEn":"Submit outputs, baseline differences, rejected misconceptions and limits for deployment separation; explain why this claim fails: Three same-host processes prove institutional noncollusion.","knowledge":[{"id":"a375-v11-32-k1","title":"原理與架構依據","titleEn":"Principle and architecture","text":"模擬三個程序不等於真實獨立信任域。","textEn":"Three simulated processes are not independent trust domains.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-educational-analysis"},{"id":"a375-v11-32-k2","title":"辨別模型的證據","titleEn":"Discriminating model evidence","text":"分開標示本地驗證與實際信任部署要求。 保留基準、輸入版本、單位與誤差範圍；這項證據只支援已列出的模型邊界，不能自動推廣為整套真實系統保證。","textEn":"Distinguish local validation from actual trust-domain requirements. Preserve baselines, input versions, units and errors; this evidence supports stated model boundaries, not an automatic guarantee for an entire real system.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-validation-plan"},{"id":"a375-v11-32-k3","title":"本課量化算例","titleEn":"Course quantitative example","text":"玩具模環 Z₁₇ 將秘密 s=9 分享為 4、7、15，因為 (4+7+15) mod17=9。每個分享若按正確隨機協議產生可隱藏原值；此固定例子不構成安全實作。加上公開值 3 後可只改一個分享為 7，和變為 12。","textEn":"Toy shares 4,7,15 in Z17 sum to secret 9. Secure hiding requires a correct randomized protocol; these fixed numbers are not a secure implementation. Adding public 3 to one share changes the reconstructed sum to 12.","sourceIds":["v11c-mpc","v11c-mpcsrc"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"審查「部署分離」的驗證方法時，哪個說法成立？","questionEn":"Which validation approach is justified for deployment separation?","options":["同機三個程式證明了跨機構不串通。","分開標示本地驗證與實際信任部署要求。","先把「部署分離」的顯示結果調到符合預期，再把這次吻合當作獨立驗證。"],"optionsEn":["Three same-host processes prove institutional noncollusion.","Distinguish local validation from actual trust-domain requirements.","Tune the displayed deployment separation result to the expected value and count that agreement as independent validation."],"answer":1,"explanation":"模擬三個程序不等於真實獨立信任域。 分開標示本地驗證與實際信任部署要求。 因此「同機三個程式證明了跨機構不串通。」混淆了本單元必須分開檢查的條件。","explanationEn":"Three simulated processes are not independent trust domains. Distinguish local validation from actual trust-domain requirements. The alternative \"Three same-host processes prove institutional noncollusion.\" conflates conditions that must be checked separately."}}]}],"curriculumVersion":11,"scope":"公開原理的本地科教模擬與工程判讀。只使用自製、合成或明確授權的資料；不操作真實受害主機、他人帳號、工業控制或超算設施。數值不代表廠商規格或實測效能，完成課程不是專業資格、真實裝置操作經歷或生產部署認證。","scopeEn":"Local educational simulation and engineering interpretation of public principles. Use self-made, synthetic or explicitly licensed data only; do not operate real victim hosts, other accounts, industrial control or supercomputing facilities. Values are not product specifications or measured performance. Completion is not a qualification, real-equipment experience or production-deployment certification.","workedExample":{"title":"含假設的可重算工程例","titleEn":"Reproducible assumed engineering case","text":"玩具模環 Z₁₇ 將秘密 s=9 分享為 4、7、15，因為 (4+7+15) mod17=9。每個分享若按正確隨機協議產生可隱藏原值；此固定例子不構成安全實作。加上公開值 3 後可只改一個分享為 7，和變為 12。","textEn":"Toy shares 4,7,15 in Z17 sum to secret 9. Secure hiding requires a correct randomized protocol; these fixed numbers are not a secure implementation. Adding public 3 to one share changes the reconstructed sum to 12.","assumptions":"使用算例明列的單位、分佈、精度、拓撲與理想化條件；改變鄰接、位寬、取樣或系統邊界必須重算。","assumptionsEn":"Use the stated units, distributions, precision, topology and idealizations; recompute after changing adjacency, width, sampling or boundaries.","sourceScope":"作者獨立設定的假想數值例，非引用機構的實測資料；來源支援領域定義與架構。","sourceScopeEn":"Independently chosen hypothetical values, not institutional measurements; sources support definitions and architecture."},"diagram":{"type":"network","labels":["參與與威脅","分享與運算","協議與故障","輸出與驗證"],"labelsEn":["Parties and threats","Sharing and computation","Protocols and failures","Outputs and validation"],"original":true,"notToScale":true},"educationEdition":11,"subcategory":"it-privacy","subcategoryTitle":"隱私保護與安全計算","subcategoryTitleEn":"Privacy-preserving and secure computation","learningTrack":"computing","learningSubdiscipline":"it-privacy","enrichmentVersion":11}};
